package eu.europa.esig.dss.eaa.sd.jwt.revocation.validation.statuslist;

import eu.europa.esig.dss.eaa.sd.jwt.validation.SDJWTCompactAttestationDocumentAnalyzer;
import eu.europa.esig.dss.eaa.revocation.validation.AttestationRevocationValidator;
import eu.europa.esig.dss.eaa.revocation.validation.statuslist.ETSI194721V121AttestationStatusListValidator;
import eu.europa.esig.dss.enumerations.AttestationStatus;
import eu.europa.esig.dss.model.InMemoryDocument;
import eu.europa.esig.dss.spi.eaa.Attestation;
import eu.europa.esig.dss.spi.eaa.AttestationPresentation;
import eu.europa.esig.dss.spi.eaa.AttestationRevocationToken;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ETSI194721V121AttestationTokenStatusListValidatorTest {

    @Test
    void test() {
        String sdjwt = "..ZZT9r2SwGzg1gygKe1A7fElK2Ppuf_YmhsPkKyK_mbQoHNWX5NBkC-qFPbK5CHf2mQCgK4WmtovGhG59EqBBCQ~";
        String eaaStatusList = ".eyJzdWIiOiJodHRwczovL2Rzcy5ub3dpbmEubHUvcGtpLWZhY3RvcnkvZWFhL3N0YXR1c19saXN0Iiwic3RhdHVzX2xpc3QiOnsiYml0cyI6MSwibHN0IjoiZU5wallJQUFBQUFJQUFFIn0sImV4cCI6MTgxMDEzNzY4OSwiaWF0IjoxNzgxMjgwMDkxfQ.ob54Z3sVs7H3otI3uqGoXh8wDEypqzERUAPZrprC5tgVw_mqIOylpJ_isfAFDx1C0_Lplo20km-FTg8UmbrTeOrY4NO8rkT3T8WB-zcoNg21XPaCWBcfKiK7gOgPmSunxzfcFipKOH9v29_eqdxtnuTl31YDU3M2Dju9IUsLot4WYgdZ_3v8W0BwQ1O4j6bb_DMKCJcPxBn_gkkdiZYudlWQYSNLBhMaeD8dFZJyxICQJ6Y2b6yVge5VgFCO9QjvhbUn3p7QoohPxqlHpK6l5KdTBsJTaudojlE-FQJPm-9fJ_cuadQlf6b-O3Hw4cMz3DP9OVRGuurn4SGsfxWzLA";

        AttestationPresentation attestationPresentation = new SDJWTCompactAttestationDocumentAnalyzer(new InMemoryDocument(sdjwt.getBytes())).getAttestationPresentation();
        List<Attestation> electronicAttestationsOfAttributes = attestationPresentation.getElectronicAttestationsOfAttributes();

        Attestation attestation = electronicAttestationsOfAttributes.get(0);

        AttestationRevocationValidator validator = new ETSI194721V121AttestationStatusListValidator();
        assertTrue(validator.isSupported(attestation));

        List<String> uris = validator.getUris(attestation);
        assertEquals(1, uris.size());

        AttestationRevocationToken attestationRevocationToken = validator.validate(attestation, eaaStatusList.getBytes());
        assertNotNull(attestationRevocationToken);
        assertEquals(AttestationStatus.VALID, attestationRevocationToken.getStatus());
        assertArrayEquals(eaaStatusList.getBytes(), attestationRevocationToken.getEncoded());
        assertNotNull(attestationRevocationToken.getCreationDate());
        assertNotNull(attestationRevocationToken.getExpirationDate());
        assertEquals(uris.get(0), attestationRevocationToken.getSubject());
    }

    @Test
    void ietfTest() {
        String sdjwt = "..jgYfbOpKZZREkEo1ZrlSVu_zam7uZtLbyMy_Kz_rGzi5ymu4CALi8UPwxuLcMp1dZHENLB_sb49QEtdr5rv3Aw~";
        String eaaStatusList = ".eyJzdWIiOiJodHRwczovL2Rzcy5ub3dpbmEubHUvcGtpLWZhY3RvcnkvZWFhL3N0YXR1c19saXN0Iiwic3RhdHVzX2xpc3QiOnsiYml0cyI6MSwibHN0IjoiZU5wallJQUFBQUFJQUFFIn0sImV4cCI6MTgwOTk0NzQzMywiaWF0IjoxNzgxMDg5ODM1fQ.Dkk5gbdVXw8IdKzwBIZfcfdWVtKaMQy_31dEstj7Z-MuxBnfyKBOy5l9GA0Q1bYLo6XILJL6xcd5yB68JeCnhT-fhfb-c_U7a0u_ufSBGQv7HbeKFk5kIftWX32dt13vINefv8YT5ULMPgnceXoGSM2lj-atMzqC4XmU6gdi_u7sCOajk_ZLGJwdGdwKXhvGlUO3pogaT4Nc_02hqJFbrN5pMteDAnNw6NrGqtnzfqBSLDnGxG3txi-liUp2tszs-XJtlHUVIyzKzpEcdq25UNNQb3OnTiZ0gXkMo3d1Y_QgoCFJiBnPr1aDqqfizjKnAgbYOLxgtF1M8MjdUpw4nw";

        AttestationPresentation attestationPresentation = new SDJWTCompactAttestationDocumentAnalyzer(new InMemoryDocument(sdjwt.getBytes())).getAttestationPresentation();
        List<Attestation> electronicAttestationsOfAttributes = attestationPresentation.getElectronicAttestationsOfAttributes();

        Attestation attestation = electronicAttestationsOfAttributes.get(0);

        AttestationRevocationValidator validator = new ETSI194721V121AttestationStatusListValidator();
        assertFalse(validator.isSupported(attestation));

        Exception exception = assertThrows(UnsupportedOperationException.class, () -> validator.getUris(attestation));
        assertEquals("The provided EAA token does not contain 'status' or not supported!", exception.getMessage());

        exception = assertThrows(UnsupportedOperationException.class, () -> validator.validate(attestation, eaaStatusList.getBytes()));
        assertEquals("The provided EAA token does not contain 'status' or not supported!", exception.getMessage());
    }

}
